-- Explicit job context and idempotency, TEST only.
begin;
do $$begin if current_setting('mir.target_project',true) is distinct from 'hxtztkmbfpmzrieccwsg' then raise exception 'MIR TEST prerequisite required';end if;end$$;
create or replace function public.mir_lead_action(org uuid,request_id uuid,action text,payload jsonb) returns jsonb
language plpgsql security definer set search_path=pg_catalog,mir_core as $$declare a mir_core.team_day_assignments;eid uuid;status text;prior mir_core.field_action_receipts;result jsonb;begin
 if coalesce(mir_core.staff_role(org),'')<>'chef_equipe' or request_id is null then raise exception 'Chef équipe requis' using errcode='42501';end if;
 select * into a from mir_core.team_day_assignments x where x.organization_id=org and x.work_date=current_date and x.leader_id=auth.uid() and (nullif(payload->>'jobId','') is null or x.job_id=(payload->>'jobId')::uuid) order by x.created_at desc limit 1;
 if a.id is null then raise exception 'Aucune affectation aujourd’hui' using errcode='42501';end if;
 if not coalesce(mir_core.job_allowed(org,a.job_id),false) or not exists(select 1 from mir_core.jobs j where j.organization_id=org and j.id=a.job_id and not j.archived) then raise exception 'Chantier non autorisé' using errcode='42501';end if;
 if coalesce(jsonb_typeof(payload),'null')<>'object' or length(payload::text)>12000 then raise exception 'Demande invalide' using errcode='22023';end if;
 if exists(select 1 from jsonb_object_keys(payload) k where not(k=any(case action when 'attendance' then array['jobId','userId','status'] when 'task_add' then array['jobId','title'] when 'task_complete' then array['jobId','id'] when 'material_request' then array['jobId','orderId','item','quantity','note','photoPath','urgency'] when 'field_issue' then array['jobId','note','photoPath','audioPath','urgency'] when 'daily_report' then array['jobId','workDone','hadProblem','missingMaterial','photoPaths','comment'] else array[]::text[] end))) then raise exception 'Champ non autorisé' using errcode='22023';end if;
 if exists(select 1 from jsonb_each(payload) x where case when x.key in('hadProblem','missingMaterial') then jsonb_typeof(x.value)<>'boolean' when x.key='quantity' then jsonb_typeof(x.value)<>'number' when x.key='photoPaths' then jsonb_typeof(x.value)<>'array' else jsonb_typeof(x.value)<>'string' end) then raise exception 'Type de champ invalide' using errcode='22023';end if;
 if exists(select 1 from (select payload->>'photoPath' p union all select payload->>'audioPath' union all select jsonb_array_elements_text(coalesce(payload->'photoPaths','[]'::jsonb))) photos where coalesce(p,'')<>'' and (split_part(p,'/',1)<>org::text or split_part(p,'/',2) not in('material','problem','report') or split_part(p,'/',3)<>a.job_id::text or split_part(p,'/',4)<>auth.uid()::text or p like '%..%' or not exists(select 1 from storage.objects o where o.bucket_id='mir-internal' and o.name=p))) then raise exception 'Photo inaccessible' using errcode='42501';end if;

 if action='material_request' and nullif(payload->>'orderId','') is not null and not exists(select 1 from mir_core.orders o where o.organization_id=org and o.id=(payload->>'orderId')::uuid and o.job_id=a.job_id) then raise exception 'Commande non autorisée sur ce chantier' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(org::text||auth.uid()::text||request_id::text,0));
 select * into prior from mir_core.field_action_receipts x where x.organization_id=org and x.actor_id=auth.uid() and x.request_id=mir_lead_action.request_id;
 if found then if prior.job_id<>a.job_id or prior.kind<>'lead:'||action or prior.payload<>payload then raise exception 'Clé déjà utilisée' using errcode='22023';end if;return prior.result;end if;
 if action='attendance' then eid:=(payload->>'userId')::uuid;status:=payload->>'status';if coalesce(status,'') not in ('present','absent','unconfirmed') or not exists(select 1 from mir_core.team_members where organization_id=org and team_id=a.team_id and user_id=eid and active) then raise exception 'Présence invalide' using errcode='22023';end if;insert into mir_core.team_attendance values(org,a.id,eid,status,auth.uid(),now()) on conflict(organization_id,assignment_id,user_id) do update set status=excluded.status,confirmed_by=auth.uid(),confirmed_at=now();
 elsif action='task_add' then insert into mir_core.team_tasks(organization_id,team_id,job_id,title,created_by) values(org,a.team_id,a.job_id,btrim(payload->>'title'),auth.uid()) returning id into eid;
 elsif action='task_complete' then eid:=(payload->>'id')::uuid;update mir_core.team_tasks set completed_at=coalesce(completed_at,now()),completed_by=auth.uid() where organization_id=org and id=eid and team_id=a.team_id and job_id=a.job_id;if not found then raise exception 'Tâche non autorisée' using errcode='42501';end if;
 elsif action='material_request' then insert into mir_core.material_requests(organization_id,job_id,team_id,order_id,item,quantity,note,photo_path,urgency,requested_by,client_request_id) values(org,a.job_id,a.team_id,nullif(payload->>'orderId','')::uuid,btrim(payload->>'item'),(payload->>'quantity')::numeric,left(coalesce(payload->>'note',''),1200),nullif(payload->>'photoPath',''),coalesce(nullif(payload->>'urgency',''),'normal'),auth.uid(),request_id) on conflict(organization_id,requested_by,client_request_id) do nothing returning id into eid;
 elsif action='field_issue' then insert into mir_core.field_issues(organization_id,job_id,team_id,note,photo_path,audio_path,urgency,reported_by,client_request_id) values(org,a.job_id,a.team_id,btrim(payload->>'note'),nullif(payload->>'photoPath',''),nullif(payload->>'audioPath',''),coalesce(nullif(payload->>'urgency',''),'normal'),auth.uid(),request_id) on conflict(organization_id,reported_by,client_request_id) do nothing returning id into eid;
 elsif action='daily_report' then insert into mir_core.daily_reports(organization_id,job_id,team_id,leader_id,work_done,had_problem,missing_material,photo_paths,comment,client_request_id) values(org,a.job_id,a.team_id,auth.uid(),btrim(payload->>'workDone'),coalesce((payload->>'hadProblem')::boolean,false),coalesce((payload->>'missingMaterial')::boolean,false),coalesce(payload->'photoPaths','[]'),left(coalesce(payload->>'comment',''),1200),request_id) on conflict(organization_id,leader_id,client_request_id) do nothing returning id into eid;
 else raise exception 'Action inconnue' using errcode='22023';end if;
 if eid is null then raise exception 'Action existante à vérifier' using errcode='23505';end if;
 if action<>'attendance' then insert into mir_core.job_activity(organization_id,job_id,activity_type,entity_id,actor_id,payload) values(org,a.job_id,case action when 'task_add' then 'task' when 'task_complete' then 'task' when 'material_request' then 'material_request' when 'field_issue' then 'field_issue' else 'daily_report' end,eid,auth.uid(),payload);end if;
 if action in ('material_request','field_issue','daily_report') then insert into mir_core.notifications(organization_id,user_id,kind,title,route,entity_id) select org,s.user_id,action,case action when 'material_request' then 'Demande de matériel' when 'field_issue' then 'Problème chantier' else 'Rapport de fin de journée' end,jsonb_build_object('view','boss','jobId',a.job_id,'entityId',eid),eid from mir_core.staff_capabilities s where s.organization_id=org and s.active and s.staff_role='boss';end if;
 result:=jsonb_build_object('ok',true,'id',eid,'jobId',a.job_id);insert into mir_core.field_action_receipts values(org,auth.uid(),request_id,a.job_id,'lead:'||action,payload,result);return result;end$$;

commit;
